const rows = $input.all().map(r => r.json);
const categoria = ($('When Executed by Another Workflow').first().json.categoria || '').trim();

if (!rows || rows.length === 0) {
  const msg = categoria
    ? `No encontré productos en la categoría "${categoria}". Por favor, consulta nuestro menú.`
    : 'No hay productos disponibles en este momento.';
  return [{ json: { respuesta_agente: msg, total_items: 0 } }];
}

// Abreviaturas para variantes/tamaños comunes
const ABREV = {
  // Tamaños pizza
  'personal': 'P.',
  'personal (25 cm)': 'P. 25cm',
  'mediana': 'M.',
  'mediana (32 cm)': 'M. 32cm',
  'familiar': 'F.',
  'familiar (45 cm)': 'F. 45cm',
  'única': 'Única',
  'unica': 'Única',
  'pequena': 'Peq.',
  'pequeña': 'Peq.',
  'pequeño': 'Peq.',
  'grande': 'G.',
  'extra grande': 'XL',
  'xl': 'XL',
  'small': 'S.',
  'estándar': 'Std.',
  'estandar': 'Std.',
  'individual': 'Ind.',
  // Raciones
  'ración': 'Rac.',
  'racion': 'Rac.',
  'ración individual': 'Rac. Ind.',
  'racion individual': 'Rac. Ind.',
  'ración grande': 'Rac. G.',
  'racion grande': 'Rac. G.',
  'ración grande (14 uds)': 'Rac. G. 14u',
  'racion grande (14 uds)': 'Rac. G. 14u',
  'ración (6 uds)': 'Rac. 6u',
  'racion (6 uds)': 'Rac. 6u',
  'ración (8 uds)': 'Rac. 8u',
  'racion (8 uds)': 'Rac. 8u',
  // Bebidas
  'lata 330 ml': 'Lata',
  'botella 500 ml': '500ml',
  'botella 1.5 l': '1,5L',
  'botella 1,5 l': '1,5L',
};

function abreviar(nombre) {
  const key = nombre.trim().toLowerCase();
  return ABREV[key] || nombre;
}

// Agrupar por categoría
const cats = {};
for (const row of rows) {
  const cat = row.category_name || 'Otros';
  if (!cats[cat]) cats[cat] = {};
  const item = row.item_name;
  if (!cats[cat][item]) {
    cats[cat][item] = { available: row.is_active !== false, variants: [] };
  }
  if (row.variant_name && row.price != null) {
    cats[cat][item].variants.push({ name: row.variant_name, price: row.price });
  }
}

const lines = [];
for (const [cat, items] of Object.entries(cats)) {
  lines.push(`*${cat}*`);
  for (const [itemName, data] of Object.entries(items)) {
    const avail = data.available ? '' : ' _(no disp.)_';
    if (data.variants.length === 0) {
      lines.push(`- ${itemName}${avail}`);
    } else {
      const vStr = data.variants
        .map(v => `${abreviar(v.name)} €${Number(v.price).toFixed(2).replace('.',',')}`)
        .join(' / ');
      lines.push(`- ${itemName}: ${vStr}${avail}`);
    }
  }
  lines.push('');
}

const totalItems = Object.values(cats).reduce((acc, items) => acc + Object.keys(items).length, 0);
const header = categoria ? `*${categoria}*\n` : '';
const respuesta = header + lines.join('\n').trim();

return [{ json: { respuesta_agente: respuesta, total_items: totalItems } }];
